CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "two_factor_secret" text, "two_factor_recovery_codes" text, "two_factor_confirmed_at" datetime, "role" varchar check ("role" in ('user', 'moderator', 'admin')) not null default 'user', "img" varchar, "active" tinyint(1) not null default '1', "surname" varchar);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE TABLE IF NOT EXISTS "countries" ("code" varchar not null, "name" varchar not null, "nationality" varchar, "img" varchar, primary key ("code"));
CREATE TABLE IF NOT EXISTS "user_country" ("id" integer primary key autoincrement not null, "user_id" integer not null, "country_code" varchar not null, foreign key("user_id") references "users"("id") on delete cascade, foreign key("country_code") references "countries"("code") on delete cascade);
CREATE UNIQUE INDEX "user_country_user_id_country_code_unique" on "user_country" ("user_id", "country_code");
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" varchar, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "categories_name_unique" on "categories" ("name");
CREATE TABLE IF NOT EXISTS "posts" ("id" integer primary key autoincrement not null, "user_id" integer not null, "title" varchar not null, "content" text not null, "experience_date" date, "image" varchar, "latitude" numeric, "longitude" numeric, "country_code" varchar, "status" varchar check ("status" in ('draft', 'published', 'rejected')) not null default 'draft', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("country_code") references "countries"("code") on delete set null);
CREATE TABLE IF NOT EXISTS "post_category" ("id" integer primary key autoincrement not null, "post_id" integer not null, "category_id" integer not null, foreign key("post_id") references "posts"("id") on delete cascade, foreign key("category_id") references "categories"("id") on delete cascade);
CREATE UNIQUE INDEX "post_category_post_id_category_id_unique" on "post_category" ("post_id", "category_id");
CREATE TABLE IF NOT EXISTS "post_country" ("id" integer primary key autoincrement not null, "post_id" integer not null, "country_code" varchar not null, foreign key("post_id") references "posts"("id") on delete cascade, foreign key("country_code") references "countries"("code") on delete cascade);
CREATE UNIQUE INDEX "post_country_post_id_country_code_unique" on "post_country" ("post_id", "country_code");
CREATE TABLE IF NOT EXISTS "ratings" ("id" integer primary key autoincrement not null, "user_id" integer not null, "post_id" integer not null, "value" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("post_id") references "posts"("id") on delete cascade);
CREATE UNIQUE INDEX "ratings_user_id_post_id_unique" on "ratings" ("user_id", "post_id");
CREATE TABLE IF NOT EXISTS "reports" ("id" integer primary key autoincrement not null, "user_id" integer not null, "post_id" integer not null, "reason" varchar not null, "status" varchar check ("status" in ('pending', 'dismissed', 'accepted')) not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("post_id") references "posts"("id") on delete cascade);
CREATE UNIQUE INDEX "reports_user_id_post_id_unique" on "reports" ("user_id", "post_id");
CREATE TABLE IF NOT EXISTS "notifications" ("id" integer primary key autoincrement not null, "sender_id" integer not null, "receiver_id" integer not null, "message" varchar not null, "read" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("sender_id") references "users"("id") on delete cascade, foreign key("receiver_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "contact_messages" ("id" integer primary key autoincrement not null, "user_id" integer not null, "type" varchar check ("type" in ('suggestion', 'technical_issue', 'account', 'other')) not null, "subject" varchar not null, "message" text not null, "status" varchar check ("status" in ('pending', 'in_review', 'resolved')) not null default 'pending', "created_at" datetime not null default CURRENT_TIMESTAMP, "updated_at" datetime not null default CURRENT_TIMESTAMP, foreign key("user_id") references "users"("id") on delete cascade);
